package com.customcharge.persistencelayer.config.datasource;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.slf4j.MDC;import org.springframework.jdbc.datasource.lookup.AbstractRoutingDataSource;import org.springframework.transaction.support.TransactionSynchronizationManager;import java.util.concurrent.atomic.LongAdder;public class RoutingDataSource extends AbstractRoutingDataSource {    private static final Logger log = LoggerFactory.getLogger(RoutingDataSource.class);    private static final String TRACE_ID_MDC = "traceId";    private final boolean fallbackToWrite;    private final boolean readPoolConfigured;    private final LongAdder readCount = new LongAdder();    private final LongAdder writeCount = new LongAdder();    public RoutingDataSource(boolean fallbackToWrite, boolean readPoolConfigured) {        this.fallbackToWrite = fallbackToWrite;        this.readPoolConfigured = readPoolConfigured;    }    @Override    protected Object determineCurrentLookupKey() {        boolean txReadOnly = TransactionSynchronizationManager.isCurrentTransactionReadOnly();        DataSourceRoute route;        if (!txReadOnly) {            route = DataSourceRoute.WRITE;        } else if (fallbackToWrite && !readPoolConfigured) {            route = DataSourceRoute.WRITE;        } else {            route = DataSourceRoute.READ;        }        if (route == DataSourceRoute.READ) {            readCount.increment();        } else {            writeCount.increment();        }        if (log.isDebugEnabled()) {            log.debug("DB route selected route={} txReadOnly={} traceId={} readCount={} writeCount={}",                    route,                    txReadOnly,                    MDC.get(TRACE_ID_MDC),                    readCount.sum(),                    writeCount.sum());        }        return route;    }}